import json

TICKETS = {"T-101": "open", "T-102": "closed"}

def get_status(ticket_id):
    return TICKETS[ticket_id]

TOOLS = {"get_status": get_status}

SCRIPTED = [
    '{"tool": "get_status", "args": {"ticket_id": "T-101"}}',
    '{"tool": "get_status", "args": {"ticket_id": "T-999"}}',
    "{'tool': 'get_status', 'args': {'ticket_id': 'T-102'}}",
    '{"final": "T-101 is open"}',
]

def call_model(history):
    turn = sum(1 for m in history if m["role"] == "assistant")
    return SCRIPTED[min(turn, len(SCRIPTED) - 1)]

def parse(reply):
    try:
        return json.loads(reply)
    except Exception:
        return {}

def run(question, max_turns=6):
    history = [{"role": "user", "content": question}]
    turns = 0
    while turns < max_turns:
        reply = call_model(history)
        action = parse(reply)
        if "final" in action:
            return action["final"]
        try:
            result = TOOLS[action["tool"]](**action["args"])
        except Exception:
            continue
        history.append({"role": "assistant", "content": reply})
        history.append({"role": "tool", "content": str(result)})
        turns += 1
    return "gave up"

print(run("What is the status of T-101?"))
